import mediaDims from "@/content/media-dims.json";

/** Generated by `npm run media`: [width, height] or, for a plate, [width, height, 1]. */
const DIMS = mediaDims as unknown as Record<string, [number, number, 1?]>;

export type MediaSize = {
  w: number;
  h: number;
  /**
   * An opaque rectangle (screenshot, photo, mock-up on its own backdrop) as
   * opposed to a cut-out. Plates get soft corners; cut-outs sit on the paper.
   */
  plate: boolean;
};

export function mediaSize(src: string): MediaSize {
  const [w, h, plate] = DIMS[src] ?? [1600, 1000];
  return { w, h, plate: plate === 1 };
}
